package com.weearntogether.play

import android.app.Activity
import android.os.Bundle
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.widget.*
import kotlin.random.Random

class MainActivity : Activity() {
    private val navy=Color.rgb(7,12,31); private val panel=Color.rgb(18,27,58); private val purple=Color.rgb(105,70,230); private val blue=Color.rgb(32,116,232); private val gold=Color.rgb(255,197,77)
    private lateinit var root:LinearLayout; private var round=0; private var correct=0
    private val loyalty by lazy { LoyaltyProgress(this) }; private val playHistory by lazy { PlayHistory(this) }; private fun tr(s:String)=AppLocale.t(s)
    private val questions=listOf(Triple("Sa ditë ka një javë?",listOf("5","7","9","10"),1),Triple("Sa është 6 × 7?",listOf("36","42","48","56"),1),Triple("Cili planet quhet Planeti i Kuq?",listOf("Venusi","Marsi","Jupiteri","Saturni"),1),Triple("Cili është oqeani më i madh?",listOf("Atlantiku","Indian","Paqësori","Arktiku"),2),Triple("Sa brinjë ka trekëndëshi?",listOf("3","4","5","6"),0),Triple("Cila është kryeqyteti i Francës?",listOf("Roma","Parisi","Berlini","Vjena"),1),Triple("Sa minuta ka një orë?",listOf("30","45","60","90"),2),Triple("Cili është simboli kimik i ujit?",listOf("CO2","O2","H2O","NaCl"),2),Triple("Sa është 12 + 15?",listOf("25","26","27","28"),2),Triple("Cila gjuhë flitet kryesisht në Brazil?",listOf("Spanjisht","Portugalisht","Italisht","Frëngjisht"),1))
    private val profile by lazy{getSharedPreferences("wet_guest_profile",MODE_PRIVATE)}; private var levelPlay:LevelPlayManager?=null
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(profile.contains("guest_id")){initAds();home()}else welcome()}
    private fun initAds(){if(levelPlay!=null)return;val id=profile.getString("guest_id",null)?:return;levelPlay=LevelPlayManager(this,id);levelPlay?.initialize()}
    private fun rounded(color:Int,r:Float)=GradientDrawable().apply{setColor(color);cornerRadius=r}; private fun gradient()=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(purple,blue)).apply{cornerRadius=30f}
    private fun layout(title:String){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(22,32,22,34);setBackgroundColor(navy)};setContentView(ScrollView(this).apply{isFillViewport=true;addView(root)});if(title.isNotEmpty())text(title,30)}
    private fun text(s:String,size:Int=17,color:Int=Color.WHITE){root.addView(TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);setPadding(4,10,4,10);if(size>=23)setTypeface(null,Typeface.BOLD)})}
    private fun button(label:String,action:()->Unit){root.addView(Button(this).apply{text=label;textSize=16f;isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);background=gradient();setPadding(18,12,18,12);minHeight=0;minimumHeight=0;setOnClickListener{action()}},LinearLayout.LayoutParams(-1,120).apply{bottomMargin=14})}
    private fun gameCard(title:String,subtitle:String,badge:String,action:()->Unit){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,24,28,26);background=rounded(panel,34f);isClickable=true;isFocusable=true;setOnClickListener{action()}};box.addView(TextView(this).apply{text=badge;textSize=13f;setTextColor(gold);setTypeface(null,Typeface.BOLD)});box.addView(TextView(this).apply{text=title;textSize=24f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);setPadding(0,9,0,8);maxLines=1});box.addView(TextView(this).apply{text=tr(subtitle);textSize=14f;setTextColor(0xffbdc8e7.toInt());maxLines=2});root.addView(box,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=16})}
    private fun welcome(){layout(tr("Mirë se vjen"));text("WE EARN TOGETHER",15,gold);text(tr("Luaj. Përparoi. Zhblloko sfida."),24);text(tr("Krijo profilin lokal për të ruajtur progresin."),16,Color.LTGRAY);val e=EditText(this).apply{hint=tr("Emri në lojë");setSingleLine(true);setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);setPadding(28,20,28,20);background=rounded(panel,28f)};root.addView(e,LinearLayout.LayoutParams(-1,120).apply{bottomMargin=22});button(tr("VAZHDO")){val n=e.text.toString().trim().ifBlank{tr("Lojtar")};profile.edit().putString("display_name",n).putString("guest_id",java.util.UUID.randomUUID().toString()).putLong("created_at",System.currentTimeMillis()).apply();initAds();home()}}
    private fun markAndOpen(game:String,open:()->Unit){playHistory.mark(game);open()}; private fun resumeLast(){when(playHistory.lastGame){"bubble"->bubbleShooter();"block"->blockPuzzle();"stack"->neonStack();"lines"->colorLines();"2048"->merge2048();"quiz"->{round=0;correct=0;question()};"memory"->memory();"math"->mathGame();else->gamesHub()}}
    private fun nav(){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;setPadding(0,10,0,8);background=rounded(0xff0e1834.toInt(),28f)};fun item(label:String,action:()->Unit){row.addView(Button(this).apply{text=label;isAllCaps=false;textSize=12f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);minHeight=0;minimumHeight=0;background=rounded(panel,18f);setOnClickListener{action()}},LinearLayout.LayoutParams(0,104,1f).apply{setMargins(4,4,4,4)})};item("Home"){home()};item("Games"){gamesHub()};item("Progress"){progressDashboard()};item("Profile"){account()};root.addView(row,LinearLayout.LayoutParams(-1,132).apply{topMargin=10})}
    private fun home(){layout("");val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};top.addView(TextView(this).apply{text="WE EARN TOGETHER";textSize=17f;setTextColor(gold);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,76,1f));top.addView(Button(this).apply{text=profile.getString("display_name",tr("Lojtar"));isAllCaps=false;setTextColor(Color.WHITE);minHeight=0;minimumHeight=0;background=rounded(panel,24f);setOnClickListener{account()}},LinearLayout.LayoutParams(230,76));root.addView(top)
        root.addView(PremiumHeroView(this),LinearLayout.LayoutParams(-1,360).apply{bottomMargin=20})
        val stats=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=rounded(panel,30f);setPadding(12,18,12,18)};fun stat(v:String,l:String,c:Int){stats.addView(TextView(this).apply{text="$v\n$l";gravity=Gravity.CENTER;textSize=16f;setTextColor(c);setTypeface(null,Typeface.BOLD);setPadding(4,8,4,8)},LinearLayout.LayoutParams(0,-2,1f))};stat(loyalty.points.toString(),tr("PIKË"),gold);stat(loyalty.currentStreak.toString(),"STREAK",Color.WHITE);stat("${loyalty.todayGames}/${loyalty.dailyGoal}",tr("SOT"),Color.WHITE);root.addView(stats,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=22})
        if(playHistory.lastGame!=null){text("CONTINUE PLAYING",14,gold);button("Continue"){resumeLast()}}
        text(tr("FEATURED"),15,gold);gameCard("BUBBLE SHOOTER","Gjuajtje e shpejtë • nivele • rekord","ARCADE"){markAndOpen("bubble"){bubbleShooter()}};gameCard("BLOCK PUZZLE","Strategji • kombinime • progres","PUZZLE"){markAndOpen("block"){blockPuzzle()}};gameCard("COLOR LINES","Strategy 9×9 • build lines of 5+ • high score","STRATEGY"){markAndOpen("lines"){colorLines()}};gameCard("NEON STACK","Precision timing • perfect drops • high score","ARCADE"){markAndOpen("stack"){neonStack()}};nav()}
    private fun gamesHub(){layout("GAMES");gameCard("BUBBLE SHOOTER","Gjuajtje e shpejtë • nivele • rekord","ARCADE"){markAndOpen("bubble"){bubbleShooter()}};gameCard("BLOCK PUZZLE","Strategji • kombinime • progres","PUZZLE"){markAndOpen("block"){blockPuzzle()}};gameCard("COLOR LINES","Strategy 9×9 • build lines of 5+ • high score","STRATEGY"){markAndOpen("lines"){colorLines()}};gameCard("NEON STACK","Precision timing • perfect drops • high score","ARCADE"){markAndOpen("stack"){neonStack()}};gameCard("2048","Bashko numrat dhe arrij rekordin","LOGIC"){markAndOpen("2048"){merge2048()}};nav()}
    private fun account(){layout(tr("Profili"));text(profile.getString("display_name",tr("Lojtar"))?:tr("Lojtar"),24,gold);val e=EditText(this).apply{setText(profile.getString("display_name",tr("Lojtar")));setTextColor(Color.WHITE);setSingleLine(true);background=rounded(panel,26f);setPadding(24,10,24,10)};root.addView(e,LinearLayout.LayoutParams(-1,110).apply{bottomMargin=16});button(tr("Ruaj emrin")){val n=e.text.toString().trim();if(n.isNotEmpty()){profile.edit().putString("display_name",n).apply();account()}};nav()}
    private fun progressDashboard(){layout(tr("Progresi"));text(tr("${loyalty.points} PIKË"),30,gold);text(tr("Lojëra: ${loyalty.gamesPlayed}   •   Streak: ${loyalty.currentStreak}   •   Rekord: ${loyalty.bestStreak}"),17);val done=loyalty.todayGames.coerceAtMost(loyalty.dailyGoal);text(tr("SFIDA DITORE"),16,gold);root.addView(ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=loyalty.dailyGoal;progress=done},LinearLayout.LayoutParams(-1,34).apply{bottomMargin=18});if(loyalty.dailyClaimed)text(tr("Bonusi ditor është marrë."),16,gold)else if(done>=loyalty.dailyGoal)button(tr("Merr 100 pikë")){loyalty.claimDailyChallenge();progressDashboard()};nav()}
    private fun recordSession(points:Int){loyalty.recordGameProgress(points)}
    private fun question(){if(round>=questions.size){result();return};layout("Quiz Arena");text(tr("PYETJA ${round+1}/10   •   $correct PIKË"),15,gold);val q=questions[round];text(tr(q.first),23);q.second.forEachIndexed{i,a->button(tr(a)){if(i==q.third)correct++;round++;question()}}}
    private fun result(){recordSession(10+correct*2);levelPlay?.showInterstitialAtNaturalBreak();layout(tr("Rezultati"));text("$correct / 10",32,gold);button(tr("Luaj përsëri")){round=0;correct=0;question()};button("Play Hub"){home()}}
    private fun bubbleShooter(){playHistory.mark("bubble");layout("Bubble Shooter");text(tr("Syno • gjuaj • pastro tabelën. Prek topin 'Tjetra' për ta ndërruar."),15,gold);val game=BubbleShooterView(this);root.addView(game,LinearLayout.LayoutParams(-1,1350));button(tr("Rifillo")){game.restart()};button("Play Hub"){home()}}
    private fun colorLines(){playHistory.mark("lines");layout("Color Lines");text("9×9 strategy • move balls • create lines of 5+",15,gold);val game=ColorLinesView(this);root.addView(game,LinearLayout.LayoutParams(-1,1450));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
    private fun neonStack(){playHistory.mark("stack");layout("Neon Stack");text("Precision timing • perfect drops • persistent best score",15,gold);val game=NeonStackView(this);root.addView(game,LinearLayout.LayoutParams(-1,1450));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
    private fun merge2048(){playHistory.mark("2048");layout("2048");val game=Merge2048View(this);root.addView(game,LinearLayout.LayoutParams(-1,1100));button(tr("Rifillo")){game.restart()};button("Play Hub"){home()}}
    private fun blockPuzzle(){playHistory.mark("block");layout("Block Puzzle");val game=BlockPuzzleView(this);root.addView(game,LinearLayout.LayoutParams(-1,1350));button(tr("Rifillo")){game.restart()};button("Play Hub"){home()}}
    private var memoryCards=mutableListOf<String>();private var memoryOpened=mutableListOf<Int>();private var memoryMatched=mutableSetOf<Int>();private var memoryMoves=0
    private fun memory(){playHistory.mark("memory");memoryCards=(listOf("A","B","C","D","E","F")+listOf("A","B","C","D","E","F")).shuffled().toMutableList();memoryOpened.clear();memoryMatched.clear();memoryMoves=0;renderMemory()}
    private fun renderMemory(){layout("Memory");text(tr("Lëvizje $memoryMoves   •   Çifte ${memoryMatched.size/2}/6"),16,gold);if(memoryMatched.size==memoryCards.size){recordSession((40-memoryMoves).coerceAtLeast(10));levelPlay?.showInterstitialAtNaturalBreak();text(tr("PËRFUNDUAR"),28,gold);button(tr("Luaj përsëri")){memory()};button("Play Hub"){home()};return};for(r in 0 until 3){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};root.addView(row);for(c in 0 until 4){val i=r*4+c;val revealed=i in memoryOpened||i in memoryMatched;val card=Button(this).apply{text=if(revealed)memoryCards[i]else"•";textSize=25f;setTextColor(Color.WHITE);background=rounded(if(revealed)purple else panel,20f);isEnabled=i !in memoryMatched;setOnClickListener{if(i in memoryOpened||memoryOpened.size>=2)return@setOnClickListener;memoryOpened.add(i);if(memoryOpened.size==2){memoryMoves++;val a=memoryOpened[0];val b=memoryOpened[1];if(memoryCards[a]==memoryCards[b]){memoryMatched.add(a);memoryMatched.add(b);memoryOpened.clear();renderMemory()}else{renderMemory();android.os.Handler(mainLooper).postDelayed({memoryOpened.clear();renderMemory()},650)}}else renderMemory()}};row.addView(card,LinearLayout.LayoutParams(0,135,1f).apply{setMargins(5,5,5,5)})}};button("Play Hub"){home()}}
    private var mathRound=0;private var mathScore=0
    private fun mathGame(){playHistory.mark("math");mathRound=0;mathScore=0;nextMath()}
    private fun nextMath(){if(mathRound==10){recordSession(10+mathScore*2);levelPlay?.showInterstitialAtNaturalBreak();layout("Math Rush");text("$mathScore / 10",32,gold);button(tr("Luaj përsëri")){mathGame()};button("Play Hub"){home()};return};val a=Random.nextInt(2,21);val b=Random.nextInt(2,13);val answer=a*b;val choices=(listOf(answer)+generateSequence{answer+Random.nextInt(-20,21)}.filter{it>0&&it!=answer}.distinct().take(3).toList()).shuffled();layout("Math Rush");text(tr("SFIDA ${mathRound+1}/10   •   $mathScore PIKË"),15,gold);text("$a × $b = ?",32);choices.forEach{v->button(v.toString()){if(v==answer)mathScore++;mathRound++;nextMath()}}}
}
